package net.officefloor.hq.app.settings;

import java.util.EnumSet;
import java.util.Locale;
import java.util.Set;

/** An action the sheet's permission matrix decides who may take, with the roles that may take it when
 * the matrix leaves it blank. */
public enum Action {
    OPEN(EnumSet.of(Role.CLERK, Role.STEWARD)),
    SETTLE(EnumSet.of(Role.CLERK, Role.STEWARD)),
    VOID(EnumSet.of(Role.CLERK, Role.STEWARD)),
    REASSIGN(EnumSet.of(Role.STEWARD)),
    CLOSE(EnumSet.of(Role.CLERK, Role.STEWARD)),
    REOPEN(EnumSet.of(Role.STEWARD));

    private final Set<Role> standing;

    Action(Set<Role> standing) {
        this.standing = standing;
    }

    /** The roles that may take the action when the matrix leaves it blank. */
    public Set<Role> standing() {
        return standing;
    }

    /** The action's name as the settings show it: open, settle, and so on. */
    public String key() {
        return name().toLowerCase(Locale.ROOT);
    }
}
package net.officefloor.hq.app.settings;

/** A user's role on a sheet. Every name is a clerk unless made a steward or a viewer. */
public enum Role {
    /** May settle a claim only when its due is at or below the sheet's clerk limit. */
    CLERK,
    /** May settle any claim. */
    STEWARD,
    /** Sees every screen and figure and may change nothing. */
    VIEWER
}
package net.officefloor.hq.app.settings;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.util.Map;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.HttpMethod;
import org.springframework.web.servlet.HandlerInterceptor;
import org.springframework.web.servlet.HandlerMapping;
import org.springframework.web.servlet.config.annotation.InterceptorRegistry;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;

/** Refuses every change a viewer asks of a sheet before it reaches its controller, so it writes nothing.
 * Reads go through, as does loading the sheet; a bulk change goes through to {@code ClaimBulkService},
 * which refuses each claim a viewer asks of it. */
@Configuration
public class ViewerGuard implements WebMvcConfigurer, HandlerInterceptor {

    private final SettingsService settings;

    public ViewerGuard(SettingsService settings) {
        this.settings = settings;
    }

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(this)
                .addPathPatterns("/api/sheets/*/**")
                .excludePathPatterns("/api/sheets/*/load", "/api/sheets/*/claims/bulk-*");
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        if (HttpMethod.GET.matches(request.getMethod()) || HttpMethod.HEAD.matches(request.getMethod())) return true;
        String user = request.getHeader("X-User");
        String sheetId = sheetId(request);
        if (user == null || user.isBlank() || sheetId == null) return true;
        if (settings.roleOf(sheetId.trim(), user.trim()) == Role.VIEWER) throw new ViewerRefusedException();
        return true;
    }

    @SuppressWarnings("unchecked")
    private static String sheetId(HttpServletRequest request) {
        Object vars = request.getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
        if (!(vars instanceof Map<?, ?> map)) return null;
        Object id = map.containsKey("sheetId") ? map.get("sheetId") : map.get("id");
        return id == null ? null : id.toString();
    }
}

